import {test,expect,type Page,type BrowserContext} from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";
import {readFileSync,writeFileSync,mkdirSync} from "node:fs";
import {join} from "node:path";
import {randomUUID,createHash} from "node:crypto";
import {Client} from "pg";
import {browserFixtureDatabaseUrl} from "../helpers/browser-database";
const origin=process.env.E2E_BASE_URL??"http://127.0.0.1:3000";
const password=()=>process.env.SYNTHETIC_SEED_PASSWORD??readFileSync(process.env.SYNTHETIC_SEED_PASSWORD_FILE??"data/secrets/seed-password","utf8").trim();
const p2EvidenceDir=process.env.NIPT_E2E_P2_EVIDENCE_DIR??".local/p2-work/browser-evidence",p2VisualDir=process.env.NIPT_E2E_P2_VISUAL_DIR??".local/ux-v2/p2-visual";
const evidence=(name:string,data:unknown)=>{mkdirSync(p2EvidenceDir,{recursive:true});writeFileSync(join(p2EvidenceDir,`${name}.json`),JSON.stringify(data,null,2));};
const tags=["wcag2a","wcag2aa","wcag21a","wcag21aa","wcag22aa"];
const suffix=()=>String(Date.now()).slice(-8)+String(Math.floor(Math.random()*1000)).padStart(3,"0");
let doctorId="",unitId="";
test.beforeEach(async({context})=>{await context.setExtraHTTPHeaders({"x-real-ip":"synthetic-p2-browser-"+randomUUID()});});
async function login(page:Page,user="synthetic.anc"){await page.goto("/login");await page.getByLabel("ชื่อผู้ใช้",{exact:true}).fill(user);await page.getByLabel("รหัสผ่าน",{exact:true}).fill(password());await page.getByRole("button",{name:"เข้าสู่ระบบ",exact:true}).click();await expect(page).toHaveURL(/\/$/);}
async function post(context:BrowserContext,path:string,body:unknown,patient=false){const name=patient?"nipt_p2_signing_csrf":"nipt_csrf";const cookie=(await context.cookies()).find(c=>c.name===name)?.value??"";return context.request.post(path,{headers:{origin,"x-csrf-token":cookie},data:body});}
async function scan(page:Page,label:string){const r=await new AxeBuilder({page}).withTags(tags).analyze();evidence(label+"-axe",{violations:r.violations,incomplete:r.incomplete});await test.info().attach(label+"-axe",{body:JSON.stringify({violations:r.violations,incomplete:r.incomplete}),contentType:"application/json"});expect(r.violations).toEqual([]);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);}
async function draw(page:Page){await page.locator("canvas").scrollIntoViewIfNeeded();const b=(await page.locator("canvas").boundingBox())!;await page.mouse.move(b.x+b.width*.15,b.y+b.height*.5);await page.mouse.down();await page.mouse.move(b.x+b.width*.4,b.y+b.height*.25,{steps:8});await page.mouse.move(b.x+b.width*.65,b.y+b.height*.65,{steps:8});await page.mouse.up();}
async function register(page:Page,lab=false){await page.goto("/cases");await page.getByRole("button",{name:lab?"ลงทะเบียนโดย Lab":"ลงทะเบียน ANC",exact:true}).click();const n=suffix().slice(-5),ln="00990"+n,hn="00990"+n;await page.getByLabel("LN HIS จำลอง",{exact:false}).fill(ln);await page.getByLabel("HN จำลอง",{exact:false}).fill(hn);await expect(page.getByLabel("หน่วยงานลงทะเบียน",{exact:false})).toHaveCount(0);if(lab){const source=page.getByLabel("แหล่งของตัวระบุ",{exact:false});await source.selectOption("TUBE_LABEL");await expect(source).toHaveValue("TUBE_LABEL");}await page.getByRole("button",{name:"ตรวจข้อมูลก่อนลงทะเบียน",exact:true}).click();await page.getByRole("button",{name:"ยืนยันลงทะเบียน",exact:true}).click();await expect(page).toHaveURL(/\/cases\/[a-f0-9-]+$/);await expect(page.getByRole("heading",{name:/LN จำลอง/})).toBeVisible();return {id:page.url().split("/").at(-1)!,ln,hn};}
async function apiCase(page:Page,lab=false){const n=suffix(),ln="990"+n,hn="990"+n;const r=await post(page.context(),"/api/p2/register",{ln,hn,unitId,origin:lab?"LAB_DIRECT":"ANC",idempotencyKey:randomUUID(),...(lab?{identifierSource:"REQUEST_FORM"}:{})});expect(r.ok()).toBe(true);return (await r.json()).caseId as string;}
async function saveRequest(page:Page,reopen=true){
 const dialog=page.getByRole("dialog");
 await dialog.getByRole("button",{name:"บันทึกร่าง",exact:true}).click();
 await expect(dialog).toHaveCount(0);
 if(reopen){await page.getByRole("button",{name:"เปิดแบบขอส่งตรวจ 5 หมวด",exact:true}).click();await expect(page.getByRole("dialog")).toBeVisible();await expect(page.locator(".save-status")).toContainText("บันทึกร่างสำเร็จ");}
}
async function fillRequest(page:Page,leaveTumorUnanswered=false,leaveHeparinUnanswered=false,leaveSCAUnanswered=false){
 await page.getByRole("button",{name:"เปิดแบบขอส่งตรวจ 5 หมวด"}).click();
 await page.getByLabel("ชื่อผู้รับบริการจำลอง",{exact:false}).fill("จำลอง: ผู้รับบริการ Browser ภาษาไทยชื่อยาวเพื่อทดสอบการแสดงผล");
 await page.getByLabel("วันเกิด",{exact:true}).fill("01/01/2538");
 await page.getByLabel("น้ำหนัก (กก.)",{exact:false}).fill("40.004");
 await page.getByLabel("ส่วนสูง (ซม.)",{exact:false}).fill("100");
 await expect(page.getByTestId("bmi")).toHaveText("40.00");
 const doctors=await page.request.get('/api/p2/doctors').then(r=>r.json());
 const doctorName=doctors.doctors.find((d:{id:string})=>d.id===doctorId).name;
 await page.getByLabel("แพทย์ผู้สั่งตรวจ",{exact:false}).fill(doctorName);await page.getByRole('option',{name:doctorName,exact:true}).click();
 await page.getByRole("button",{name:/^2\. การตั้งครรภ์/}).click();
 await page.getByLabel("วันกำหนดคลอด",{exact:false}).fill("18/03/2570");
 await page.getByLabel("วันและเวลาเจาะเลือด S1",{exact:false}).fill("01/10/2569");
 await page.getByRole("radiogroup",{name:"ประเภทครรภ์",exact:false}).locator('input[value="Singleton"]').check();
 await page.getByRole("radiogroup",{name:"พบภาวะที่ตัวอ่อนฝ่อขณะตั้งครรภ์",exact:false}).locator('input[value="No"]').check();
 await page.getByRole("button",{name:/^3\. ประวัติทางการแพทย์/}).click();
 for(const group of await page.getByRole("dialog").locator(".request-choice").all()){const field=await group.getAttribute("data-field");if(leaveTumorUnanswered&&field==="history.tumor"||leaveHeparinUnanswered&&field==="history.heparin24h.answer")continue;await group.locator('input[value="No"]').check();}
 await page.getByRole("button",{name:/^4\. ความประสงค์/}).click();
 await page.getByRole("radiogroup",{name:"ความประสงค์ทราบผลเพศทารก",exact:false}).locator('input[value="DoNotWant"]').check();
 if(!leaveSCAUnanswered)await expect(page.getByRole("radiogroup",{name:"ความประสงค์เรื่อง SCA",exact:false})).toHaveCount(0); // accepted DCC UI has no separate SCA question; never invent an answer
 await page.getByRole("button",{name:/^5\. ข้อควรทราบ/}).click();
 await saveRequest(page);
 const id=new URL(page.url()).pathname.split("/").pop()!;
 const saved=await page.request.get("/api/p2/cases/"+id).then(r=>r.json());
 expect(saved.workspace.draft.pregnancy.weightKg).toBe(40.004);
 expect(saved.workspace.draft.pregnancy.collectionSource).toBe("ANC");
}
async function modes(page:Page,requestMode:string,consentMode:string){
 await page.getByRole("button",{name:"เปลี่ยนช่องทางเอกสาร",exact:true}).click();
 await page.getByLabel("ช่องทางใบขอส่งตรวจ",{exact:true}).selectOption(requestMode);
 await page.getByLabel("ช่องทางใบยินยอม",{exact:true}).selectOption(consentMode);
 // The frozen integration baseline 9db447a already has no reason field here;
 // setModes.reason is optional. Required reasons for refusal/revocation remain tested below.
 await expect(page.getByLabel("เหตุผลเปลี่ยนช่องทางจำลอง",{exact:false})).toHaveCount(0);
 await page.getByRole("button",{name:"บันทึกช่องทาง",exact:true}).click();
 await expect(page.getByRole("dialog")).toHaveCount(0);
}
async function chooseRequestDoctor(page:Page){
 const id=new URL(page.url()).pathname.split("/").pop()!;
 const draft=(await page.request.get("/api/p2/cases/"+id).then(r=>r.json())).workspace.draft;
 if(draft.ordering.doctorVersionId===doctorId)return;
 await page.getByRole("button",{name:"เปิดแบบขอส่งตรวจ 5 หมวด"}).click();
 const options=await page.request.get('/api/p2/doctors').then(r=>r.json());
 const doctorName=options.doctors.find((d:{id:string})=>d.id===doctorId).name;
 const doctor=page.getByLabel("แพทย์ผู้สั่งตรวจ",{exact:false});await doctor.fill(doctorName);await page.getByRole('option',{name:doctorName,exact:true}).click();
 await saveRequest(page,false);
 expect((await page.request.get("/api/p2/cases/"+id).then(r=>r.json())).workspace.draft.ordering.doctorVersionId).toBe(doctorId);
}
async function prepareAndStart(page:Page,ready=true){
 await chooseRequestDoctor(page);
 await page.getByRole("button",{name:/^(เริ่ม|ดำเนินการ)ลงนามใบยินยอม$/}).click();
 const dialog=page.getByRole("dialog");
 await expect(dialog.getByLabel("แพทย์ผู้สั่งตรวจจากแบบขอส่งตรวจ",{exact:true})).not.toHaveValue("ยังไม่ได้เลือกแพทย์");
 await dialog.getByRole("button",{name:"เริ่มลงนามใบยินยอม",exact:true}).click();
 await expect(page).toHaveURL(/\/p2\/signing$/);
 if(ready)await expect(page.getByRole("heading",{name:"อ่านและรับทราบด้วยตนเองครบ 12 ข้อ"})).toBeVisible();
}
