test("older searched and later-page authorized cases retain complete round/fact/event history",async({page})=>{
 test.setTimeout(90000);await login(page);const c=await register(page);const url=browserFixtureDatabaseUrl();const db=new Client({connectionString:url});await db.connect();let foreignCase="";
 const history=async()=>{await expect(page.getByRole("heading",{name:"ประวัติรอบตัวอย่าง",exact:true})).toBeVisible();const rounds=page.getByRole("heading",{name:"ประวัติรอบตัวอย่าง",exact:true}).locator("..");await expect(rounds).toContainText("เก็บตัวอย่างเลือดครั้งที่ 1 · รอบก่อนหน้า");await expect(rounds).toContainText("เก็บตัวอย่างเลือดครั้งที่ 2 · รอบปัจจุบัน");await expect(rounds).toContainText("01/08/2569");await expect(rounds).toContainText("02/08/2569");const data=await page.request.get(`/api/p2/cases/${c.id}`).then(r=>r.json());expect(data.history.events.some((e:{event_type:string})=>e.event_type==="SYNTHETIC_HISTORY_EARLIEST")).toBe(true);const activity=page.locator(".case-activity-details");await activity.locator("summary").click();await expect(activity.locator("li")).toHaveCount(data.history.events.length);};
 try{await db.query("BEGIN");const own=(await db.query("SELECT c.current_round_id,l.id,u.id actor FROM nipt_case c JOIN case_ln l ON l.case_id=c.id CROSS JOIN app_user u WHERE c.id=$1 AND u.username='synthetic.anc'",[c.id])).rows[0];await db.query("INSERT INTO p2_collection_fact(case_id,round_id,source,collection_date,actor_id,reason) VALUES($1,$2,'ANC','2026-08-01',$3,'SYNTHETIC S1')",[c.id,own.current_round_id,own.actor]);await db.query("UPDATE specimen_round SET state='RedrawRequested' WHERE id=$1",[own.current_round_id]);const redraw=(await db.query("INSERT INTO redraw_request(case_id,source_round_id,reason_code) VALUES($1,$2,'SYNTHETIC_HISTORY') RETURNING id",[c.id,own.current_round_id])).rows[0].id;const round=(await db.query("INSERT INTO specimen_round(case_id,case_ln_id,round_number,redraw_request_id) VALUES($1,$2,2,$3) RETURNING id",[c.id,own.id,redraw])).rows[0].id;await db.query("UPDATE nipt_case SET current_round_id=$1 WHERE id=$2",[round,c.id]);await db.query("INSERT INTO p2_collection_fact(case_id,round_id,source,collection_date,actor_id,reason) VALUES($1,$2,'ANC','2026-08-02',$3,'SYNTHETIC S2')",[c.id,round,own.actor]);await db.query("INSERT INTO case_event(case_id,event_type,details,created_at) VALUES($1,'SYNTHETIC_HISTORY_EARLIEST','{}',now()-interval '1 day')",[c.id]);for(let i=0;i<55;i++)await db.query("INSERT INTO case_event(case_id,event_type,details) VALUES($1,'SYNTHETIC_HISTORY_LATER','{}')",[c.id]);const foreign=(await db.query("INSERT INTO unit(code,name) VALUES($1,'SYNTHETIC foreign history') RETURNING id",['SYNTHETIC_HISTORY_'+suffix()])).rows[0].id;
 const newer=async(unit:string)=>{for(let i=0;i<205;i++){const n=(await db.query("INSERT INTO nipt_case(registration_origin,identity_key,created_at) VALUES('ANC',repeat('a',64),now()+interval '1 day') RETURNING id")).rows[0].id;if(!foreignCase)foreignCase=n;const ln=(await db.query("INSERT INTO case_ln(case_id,ln) VALUES($1,$2) RETURNING id",[n,'990'+suffix()+String(i).padStart(3,'0')])).rows[0].id;const r=(await db.query("INSERT INTO specimen_round(case_id,case_ln_id,round_number) VALUES($1,$2,1) RETURNING id",[n,ln])).rows[0].id;await db.query("UPDATE nipt_case SET current_round_id=$1 WHERE id=$2",[r,n]);await db.query("INSERT INTO case_unit_scope(case_id,unit_id) VALUES($1,$2)",[n,unit]);}};
 await newer(foreign);await db.query("COMMIT");await page.goto("/cases");await page.getByLabel("ค้นหา LN / HN / ชื่อ-นามสกุล",{exact:false}).fill(c.ln);await page.waitForTimeout(325);await page.getByRole("link",{name:`ดูรายละเอียด LN ${c.ln}`,exact:true}).click();await history();const denied=await page.request.get(`/api/p2/cases/${foreignCase}`);expect(denied.status()).toBe(403);expect(await denied.json()).not.toHaveProperty("history");await page.goto(`/cases/${foreignCase}`);await expect(page.getByRole("alert")).toBeVisible();await expect(page.getByText("SYNTHETIC_HISTORY_EARLIEST",{exact:false})).toHaveCount(0);
 await db.query("BEGIN");await newer(unitId);await db.query("COMMIT");await page.goto("/cases");await expect(page.locator(`a[href="/cases/${c.id}"]`)).toHaveCount(0);await page.getByLabel("แสดงต่อหน้า",{exact:true}).selectOption("100");const pageSummary=page.locator("[role=status]:not([popover])").filter({hasText:/แสดง \d+–\d+ จาก \d+ รายการ/});await expect(pageSummary).toContainText("หน้า 1 จาก 3");await expect(page.getByRole("button",{name:"หน้าถัดไป",exact:true})).toBeEnabled();const link=page.getByRole("link",{name:`ดูรายละเอียด LN ${c.ln}`,exact:true});
 // the case is older than 205 newer ones: reach it by paging (the registry no longer has a "load more")
 for(let pageNumber=2;pageNumber<=3&&await link.count()===0;pageNumber++){await page.getByRole("button",{name:"หน้าถัดไป",exact:true}).click();await expect(pageSummary).toContainText(`หน้า ${pageNumber} จาก 3`);} // wait for the new page, not just an idle network
 await link.click();await history();const log=(await db.query("SELECT id FROM phi_access_log WHERE case_id=$1 AND purpose='CASE_DETAIL_VIEW'",[c.id])).rows;expect(log.length).toBeGreaterThanOrEqual(2);
 }finally{await db.end();}
});

if(process.env.E2E_SKIP_VISUAL!=="1")test("P2 deliberate visual batch with deterministic synthetic fixture",async({page})=>{
 test.setTimeout(120000);mkdirSync(p2VisualDir,{recursive:true});await login(page);const r=await post(page.context(),"/api/p2/register",{ln:"9901234567",hn:"9907654321",unitId,origin:"ANC",idempotencyKey:randomUUID()});expect(r.ok()).toBe(true);const id=(await r.json()).caseId;await page.goto(`/cases/${id}`);await fillRequest(page);
 for(const width of [375,768,1280,1440]){await page.setViewportSize({width,height:900});await page.getByRole("button",{name:/^1\. ผู้รับบริการ/}).click();await scan(page,"request-responsive-"+width);await page.screenshot({path:join(p2VisualDir,`p2-request-${width}.png`),fullPage:true});await expect(page).toHaveScreenshot(`p2-request-${width}.png`,{animations:"disabled",mask:[page.locator(".save-status")]});}
 await page.setViewportSize({width:1280,height:900});for(const step of [2,3,4,5]){await page.getByRole("button",{name:new RegExp("^"+step+"\\. ")}).click();await page.screenshot({path:join(p2VisualDir,`p2-request-step${step}.png`),fullPage:true});await expect(page).toHaveScreenshot(`p2-request-step${step}.png`,{animations:"disabled",mask:[page.locator(".save-status")]});}await page.keyboard.press("Escape");await expect(page.getByRole("dialog")).toHaveCount(0);await prepareAndStart(page);
 for(const width of [375,768,1280,1440]){await page.setViewportSize({width,height:900});await scan(page,"signing-responsive-"+width);await page.screenshot({path:join(p2VisualDir,`p2-signing-${width}.png`),fullPage:true});await expect(page).toHaveScreenshot(`p2-signing-${width}.png`,{animations:"disabled",mask:[page.locator(".panel > p").first()]});}await page.getByRole("button",{name:"ยกเลิกการลงนาม",exact:true}).click();await returnStaff(page,false);await page.goto("/cases");await page.getByLabel("ค้นหา LN / HN / ชื่อ-นามสกุล",{exact:false}).fill("9901234567");await page.waitForTimeout(325);await expect(page.locator(".registry-row")).toHaveCount(1);await expect(page.locator(".ln-tail")).toHaveText("4567");for(const width of [375,768,1280,1440]){await page.setViewportSize({width,height:900});await page.screenshot({path:join(p2VisualDir,`p2-registry-${width}.png`),fullPage:true});await expect(page).toHaveScreenshot(`p2-registry-${width}.png`,{fullPage:true,animations:"disabled"});}
});

test("USB HID LN/HN scanner Enter moves focus without submitting an incomplete registration",async({page})=>{
 await login(page);await page.goto("/cases");await page.getByRole("button",{name:"ลงทะเบียน ANC",exact:true}).click();
 let registrations=0;page.on("request",request=>{if(request.method()==="POST"&&new URL(request.url()).pathname==="/api/p2/register")registrations++;});
 const ln=page.getByTestId("scan-ln"),hn=page.getByTestId("scan-hn"),review=page.getByRole("button",{name:"ตรวจข้อมูลก่อนลงทะเบียน",exact:true});
 await ln.focus();await expect(ln).toBeFocused();await ln.fill("00");await ln.press("Enter");await expect(ln).toBeFocused();expect(registrations).toBe(0);
 await ln.fill("00990"+suffix().slice(-5));await ln.press("Enter");await expect(hn).toBeFocused();expect(registrations).toBe(0);
 await expect(review).toBeEnabled();await hn.fill("00990"+suffix().slice(-5));await hn.press("Enter");await expect(review).toBeFocused();expect(registrations).toBe(0);
 await expect(page.getByLabel("หน่วยงานลงทะเบียน",{exact:false})).toHaveCount(0);
 await page.getByRole("button",{name:"ตรวจข้อมูลก่อนลงทะเบียน",exact:true}).click();await expect(page.getByRole("heading",{name:"ตรวจทานก่อนลงทะเบียน"})).toBeVisible();expect(registrations).toBe(0);
});
